async function main(ctx) {
  const resp = ctx.lastOutputOf('discover_zones') || {};
  const zones = resp.body || [];

  // Find SERP zone
  const serpZone = zones.find(z => {
    const name = String(z.name || z.zone || '').toLowerCase();
    const type = String(z.type || z.plan_type || '').toLowerCase();
    return name.includes('serp') || type.includes('serp');
  });

  if (!serpZone) {
    throw new Error('No SERP zones found in your Bright Data account. Please create a SERP API zone first.');
  }

  const zone = serpZone.name || serpZone.zone;
  const checkOutput = ctx.lastOutputOf('check_zone') || {};

  return {
    zone: zone,
    input: checkOutput.input || {}
  };
}

