async function main(ctx) {
  const prev = ctx.lastOutputOf('select_serp_zone') || ctx.lastOutputOf('merge_zone') || {};
  const input = prev.input || {};
  const zone = prev.zone || '';
  const query = String(input.query || '');
  const engine = String(input.engine || 'google');

  if (!query) throw new Error('query is required');
  if (!zone) throw new Error('zone could not be determined');

  const encodedQuery = encodeURIComponent(query);
  let searchUrl;

  if (engine === 'bing') {
    searchUrl = `https://www.bing.com/search?q=${encodedQuery}`;
  } else {
    searchUrl = `https://www.google.com/search?q=${encodedQuery}`;
  }

  return {
    url: searchUrl,
    zone: zone,
    format: 'json'
  };
}

async function main(ctx) {
  const resp = ctx.lastOutputOf('serp_call') || {};
  const status = resp.status || 0;
  const body = resp.body;

  if (status < 200 || status >= 300) {
    throw new Error(`SERP API request failed (${status}): ${JSON.stringify(body)}`);
  }

  // Parse JSON string if needed
  if (typeof body === 'string') {
    try {
      return JSON.parse(body);
    } catch (e) {
      throw new Error(`Failed to parse SERP response: ${e.message}`);
    }
  }

  return body;
}
